import numpy as np
import random

def calculate_S(adj):
    n = adj.shape[0]
    degrees = np.sum(adj, axis=1)
    S = 0
    for i in range(n):
        for j in range(i + 1, n):
            if adj[i, j] == 1:
                S += abs(degrees[i] - degrees[j])
    return S

def hill_climbing(n, iterations=1000):
    # Random starting graph
    adj = np.zeros((n, n), dtype=int)
    for i in range(n):
        for j in range(i + 1, n):
            if random.random() < 0.5:
                adj[i, j] = adj[j, i] = 1

    current_S = calculate_S(adj)

    for _ in range(iterations):
        # Pick a random edge to flip
        i, j = random.sample(range(n), 2)
        adj[i, j] = adj[j, i] = 1 - adj[i, j]
        new_S = calculate_S(adj)

        if new_S >= current_S:
            current_S = new_S
        else:
            # backtrack
            adj[i, j] = adj[j, i] = 1 - adj[i, j]

    return current_S

def simulated_annealing(n, iterations=10000):
    adj = np.zeros((n, n), dtype=int)
    for i in range(n):
        for j in range(i + 1, n):
            if random.random() < 0.5:
                adj[i, j] = adj[j, i] = 1

    current_S = calculate_S(adj)
    best_S = current_S
    T = 1.0
    cooling_rate = 0.9999

    for i in range(iterations):
        u, v = random.sample(range(n), 2)
        adj[u, v] = adj[v, u] = 1 - adj[u, v]
        new_S = calculate_S(adj)

        delta = new_S - current_S
        if delta > 0 or random.random() < np.exp(delta / T):
            current_S = new_S
            if current_S > best_S:
                best_S = current_S
        else:
            adj[u, v] = adj[v, u] = 1 - adj[u, v]

        T *= cooling_rate

    return best_S

n_values = [4, 5, 6, 7, 8, 9, 10, 11]
results = {}
for n in n_values:
    best_found = 0
    for _ in range(10): # Multiple restarts
        res = simulated_annealing(n, 10000)
        if res > best_found:
            best_found = res
    results[n] = best_found

print(results)

