                S += abs(degrees[i] - degrees[j])
    return S, degrees

def find_best_graph(n):
    best_S = 0
    best_adj = None
    for _ in range(100000):
        adj = np.zeros((n, n), dtype=int)
        for i in range(n):
            for j in range(i + 1, n):
                if np.random.random() < 0.5:
                    adj[i, j] = adj[j, i] = 1

        # Hill climbing
        curr_S, curr_degrees = calculate_S(adj)
        for _ in range(100):
            u, v = np.random.choice(n, 2, replace=False)
            adj[u, v] = adj[v, u] = 1 - adj[u, v]
            new_S, new_degrees = calculate_S(adj)
            if new_S >= curr_S:
                curr_S = new_S
                curr_degrees = new_degrees
            else:
                adj[u, v] = adj[v, u] = 1 - adj[u, v]

        if curr_S > best_S:
            best_S = curr_S
            best_adj = adj.copy()
    return best_S, best_adj

