import numpy as np

def get_S_and_degrees(adj):
    n = adj.shape[0]
    degrees = np.sum(adj, axis=1)
    S = 0
    for i in range(n):
        for j in range(i + 1, n):
            if adj[i, j] == 1:
                S += abs(degrees[i] - degrees[j])
    return S, degrees

def fast_solve(n, iterations=10000):
    best_S = 0
    best_adj = None

    for _ in range(10):
        adj = np.zeros((n, n), dtype=int)
        for i in range(n):
            for j in range(i + 1, n):
                if np.random.random() < 0.5:
                    adj[i, j] = adj[j, i] = 1

        S, degrees = get_S_and_degrees(adj)

        for _ in range(iterations):
            u, v = np.random.choice(n, 2, replace=False)

            # To efficiently update S and degrees:
            # When flipping edge (u, v):
            # 1. Update degrees: d[u] and d[v] change.
            # 2. The edges connected to u or v will have their labels changed.

            # Let's just do it the simple way first, but with fewer iterations.
            # Actually, for n=6, it's fast enough.

            old_u_v_label = abs(degrees[u] - degrees[v]) if adj[u, v] == 1 else 0

            # New degrees
            new_degrees = degrees.copy()
            if adj[u, v] == 1:
                new_degrees[u] -= 1
                new_degrees[v] -= 1
            else:
                new_degrees[u] += 1
                new_degrees[v] += 1

            # This is still slightly slow. Let's try to compute the new_S
            # by only looking at edges connected to u and v.

            new_adj = adj.copy()
            new_adj[u, v] = new_adj[v, u] = 1 - adj[u, v]
            new_S, _ = get_S_and_degrees(new_adj)

            if new_S >= S:
                adj = new_adj
                S = new_S
                degrees = new_degrees

        if S > best_S:
            best_S = S
            best_adj = adj.copy()

    return best_S, best_adj

